person = get_selected()

if person is None:
    html("<i>A person is not selected</i>")
else:
    html(f"<h3>Other records referring to {name_of(person)}</h3>")

    # {"family": [handle, ...], "citation": [...], ...} -- one real network
    # round trip, backed by the tree's own reverse-reference index
    # server-side (gramps-web-api's find_backlink_handles()), not a scan
    # over every object of every type.
    backlinks = db.get_person_backlinks(person.handle)

    if not backlinks:
        html("<i>Nothing else in the tree refers to this person</i>")
    else:
        # Which types turn up depends on the person (a Family as father/
        # mother/child, another Person's association, ...), so each type's
        # records are fetched by looking its plural function up by name --
        # one request per type, not one per record. A function picked
        # dynamically like this isn't recognized by the auto-await
        # preprocessor (it only rewrites literal people(...) etc. call
        # sites in the source text), so `await` is written by hand here.
        fetch = {
            "person": people, "family": families, "event": events, "place": places,
            "source": sources, "citation": citations, "repository": repositories,
            "media": media, "note": notes, "tag": tags,
        }
        set_column_titles("Type", "Record")
        for obj_type, handles in backlinks.items():
            if handles:
                for record in await fetch[obj_type](f"handle in {handles!r}", limit=None):
                    row(obj_type.capitalize(), record)

person = get_selected()

if person is None:
    html("<i>A person is not selected</i>")
else:
    html(f"<h3>Children of {name_of(person)}</h3>")
    if not person.family_list:
        html("<i>This person is not a parent in any recorded family</i>")
    else:
        # One request per kind of record, not one per record: every family,
        # then every spouse and child, then the children's birth and death
        # dates (what= reaches through to each one's birth/death event).
        # "handle in [...]" needs at least one handle, hence the "if"s.
        by_handle = {f.handle: f for f in families(f"handle in {person.family_list!r}", limit=None)}
        my_families = [by_handle[h] for h in person.family_list if h in by_handle]
        spouse_of = {
            f.handle: f.mother_handle if f.father_handle == person.handle else f.father_handle
            for f in my_families
        }
        child_handles = [ref.ref for f in my_families for ref in f.child_ref_list]
        wanted = [h for h in list(spouse_of.values()) + child_handles if h]
        relatives = {p.handle: p for p in people(f"handle in {wanted!r}", limit=None)} if wanted else {}
        dates = {
            d.handle: d
            for d in filter("person", where=f"handle in {child_handles!r}", what=["birth.date", "death.date"], limit=None)
        } if child_handles else {}

        set_column_titles("Child", "Birth Date", "Death Date", "Spouse")
        for family in my_families:
            spouse = relatives.get(spouse_of[family.handle])
            for ref in family.child_ref_list:
                child_dates = dates.get(ref.ref, {})
                row(
                    relatives.get(ref.ref),
                    child_dates.get("birth.date"),
                    child_dates.get("death.date"),
                    spouse or "Unknown",
                )

person = get_selected()

if person is None:
    html("<i>A person is not selected</i>")
else:
    html(f"<h3>Events for {name_of(person)}</h3>")
    if person.event_ref_list:
        # Every event, then every place they happened at: one request
        # each, not one per record. "handle in [...]" needs at least one
        # handle, hence the "if".
        handles = [ref.ref for ref in person.event_ref_list]
        by_handle = {e.handle: e for e in events(f"handle in {handles!r}", limit=None)}
        place_handles = [e.place for e in by_handle.values() if e.place]
        place_of = {p.handle: p for p in places(f"handle in {place_handles!r}", limit=None)} if place_handles else {}

        set_column_titles("Event", "Role", "Type", "Date", "Place")
        for event_ref in person.event_ref_list:
            event = by_handle.get(event_ref.ref)
            if event is not None:
                row(event, str(event_ref.role), str(event.type), event.date, place_of.get(event.place))
    else:
        html("<i>No events exist for this person</i>")

person = get_selected()

if person is None:
    html("<i>A person is not selected</i>")
else:
    html(f"<h3>Media for {name_of(person)}</h3>")
    if person.media_list:
        # Gramplet code has no network access of its own, so there is no
        # way to fetch and embed the actual image bytes here (unlike
        # Gramps Desktop's own Gallery gramplet, which shows thumbnails) --
        # a table of the attached records is the closest equivalent.
        # Every one of them in one request, not one per media record.
        handles = [ref.ref for ref in person.media_list]
        by_handle = {m.handle: m for m in media(f"handle in {handles!r}", limit=None)}
        set_column_titles("Media", "Description", "Type", "Path")
        for handle in handles:
            item = by_handle.get(handle)
            if item is not None:
                row(item, item.desc, item.mime, item.path)
    else:
        html("<i>No media exist for this person</i>")

person = get_selected()

if person is None:
    html("<i>A person is not selected</i>")
else:
    html(f"<h3>Notes for {name_of(person)}</h3>")
    if person.note_list:
        # Every note in one request, not one per note.
        by_handle = {n.handle: n for n in notes(f"handle in {person.note_list!r}", limit=None)}
        set_column_titles("Note", "Type", "Text")
        for handle in person.note_list:
            note = by_handle.get(handle)
            if note is None:
                continue
            snippet = note.text.string.strip().replace("\n", " ")
            if len(snippet) > 80:
                snippet = snippet[:80] + "..."
            row(note, str(note.type), snippet)
    else:
        html("<i>No notes exist for this person</i>")

person = get_selected()

if person is None:
    html("<i>A person is not selected</i>")
else:
    html(f"<h3>To Do for {name_of(person)}</h3>")

    # Only this person's To Do notes, picked out by the server in one
    # request rather than fetching every note to check its type here.
    # "handle in [...]" needs at least one handle, hence the "if".
    todo_notes = (
        notes(f"handle in {person.note_list!r} and type.value == NoteType.TODO", limit=None)
        if person.note_list
        else []
    )
    if todo_notes:
        order = {handle: i for i, handle in enumerate(person.note_list)}
        set_column_titles("To Do", "Text")
        for note in sorted(todo_notes, key=lambda n: order[n.handle]):
            snippet = note.text.string.strip().replace("\n", " ")
            if len(snippet) > 200:
                snippet = snippet[:200] + "..."
            row(note, snippet)
    else:
        html("<i>No To Do notes recorded for this person</i>")
